import { describe, expect, it } from "vitest";

import { computeTax } from "../../engine/compute";
import { CLASSES, restaurantInput } from "../../engine/__tests__/fixtures/baskets";
import type { SaleForDocument } from "../../sale/types";
import type { IssuedDocument } from "../../sidecar/types";
import type { SigningMaterial } from "../port";
import { createSidecarIssuer, type SidecarFetch } from "../sidecar";
import { RECORDED_ANSWERS } from "./fixtures/recorded";

/**
 * FUT-4924's acceptance, against the fiscal service's own recorded answer
 * (`nfce-issue-2027`, regenerated by `sidecar/tests/Support/record-answers.php`):
 * an NFC-e dated after NT 2026.008's mandatory date is authorised with the
 * engine's `vProdLiq` on every item, `vUnComLiq × qCom` within ±0,01 of it
 * (rule I11c-20), and the Pix that paid it linked in `gPgtoVinc` by its txid
 * (NT 2026.006). The XSD validation of the same document is the service's
 * (`DocumentMapperTest`).
 */

interface Recording {
  readonly path: string;
  readonly request: { readonly document: SaleForDocument } & Record<string, unknown>;
  readonly status: number;
  readonly body: IssuedDocument;
}

const RECORDING = (RECORDED_ANSWERS as Readonly<Record<string, unknown>>)["nfce-issue-2027"] as Recording;
const DOCUMENT = RECORDING.request.document;

const SIGNING: SigningMaterial = {
  certificate: { pfxBase64: "UEZYLUJZVEVT", password: "pfx-password-not-a-real-one" },
  csc: { id: "000001", token: "TESTCSC0123456789ABCDEF0123456789" },
};

/** The same two items through the engine, on the same day. */
const BREAKDOWN = computeTax(
  restaurantInput(DOCUMENT.issuedAt.slice(0, 10), {
    lines: [
      { id: "line-1", valueCents: 10880, quantity: 1, foodAndDrink: true, taxClass: CLASSES.household },
      { id: "line-2", valueCents: 1999, quantity: 3, foodAndDrink: true, taxClass: CLASSES.preparedFood },
    ],
  }),
);

/** Every value of one tag, in document order. */
function tags(xml: string, name: string): string[] {
  return [...xml.matchAll(new RegExp(`<${name}>([^<]*)</${name}>`, "g"))].map((match) => match[1]!);
}

const cents = (reais: string): number => Math.round(Number(reais) * 100);

async function issued(): Promise<{ answer: IssuedDocument; sent: Record<string, unknown> }> {
  const sent: Array<Record<string, unknown>> = [];
  const fetch: SidecarFetch = async (_url, init) => {
    sent.push(JSON.parse(init.body ?? "{}") as Record<string, unknown>);
    return { status: RECORDING.status, text: async () => JSON.stringify(RECORDING.body) };
  };
  const issuer = createSidecarIssuer({ baseUrl: "http://fiscal-sidecar:8080/", fetch, timeoutMs: 90_000 });
  const outcome = await issuer.issue({ model: "NFCE", environment: "homologacao", signing: SIGNING, document: DOCUMENT });
  if (!outcome.ok) throw new Error(`expected AUTHORIZED, got ${outcome.error.class}`);
  return { answer: outcome.answer, sent: sent[0] ?? {} };
}

describe("an NFC-e after NT 2026.008's mandatory date (FUT-4924)", () => {
  it("is dated in a period whose IBS/CBS sit inside vProd, and carries the engine's figures", () => {
    expect(DOCUMENT.issuedAt >= "2027-01-01").toBe(true);
    expect(BREAKDOWN.taxInsidePrice).toBe(true);
    expect(DOCUMENT.lines.map((line) => line.netValueCents)).toEqual(BREAKDOWN.lines.map((line) => line.netValueCents));
    expect(DOCUMENT.lines.map((line) => line.ibsCbs?.figures?.baseCents)).toEqual(BREAKDOWN.lines.map((line) => line.taxBaseCents));
  });

  it("is authorised with vProdLiq equal to the engine's figure and vUnComLiq × qCom within ±0,01 of it (I11c-20)", async () => {
    const { answer, sent } = await issued();
    expect(sent["document"]).toEqual(DOCUMENT);
    expect(answer.status).toBe("AUTHORIZED");
    const xml = answer.authorizedXml;

    const netValues = tags(xml, "vProdLiq");
    expect(netValues.map(cents)).toEqual(BREAKDOWN.lines.map((line) => line.netValueCents));
    for (const [index, line] of BREAKDOWN.lines.entries()) {
      expect(Math.abs(cents(netValues[index]!) - line.netValueCents!)).toBeLessThanOrEqual(1);
    }
    const quantities = tags(xml, "qCom").map(Number);
    tags(xml, "vUnComLiq").forEach((unit, index) => {
      expect(Math.abs(Number(unit) * quantities[index]! - Number(netValues[index]))).toBeLessThanOrEqual(0.01);
    });
    expect(tags(xml, "vProdLiqTot").map(cents)).toEqual([BREAKDOWN.netValueCents]);
    expect(tags(xml, "vProd").slice(0, 2).map(cents)).toEqual([10880, 1999]);
  });

  it("links the Pix that paid it in gPgtoVinc, by its txid (NT 2026.006)", async () => {
    const { answer } = await issued();
    const txid = DOCUMENT.payments[0]?.linkedTransaction?.transactionId;
    expect(DOCUMENT.payments[0]?.method).toBe("PIX_DYNAMIC");
    expect(txid).toBe("7f3c2a91e04b4c1d9a0b11c2d3e4f5a6");
    expect(answer.authorizedXml).toMatch(new RegExp(`<gPgtoVinc><gPgto nPag="1" idTransacao="${txid}">`));
  });
});
